function sumar(nums) {
  let total = 0;
  for (const n of nums) total += n;
  return total;
}

console.log(sumar([1, 2, 3]));

for (let i = 1; i <= 15; i++) {
  if (i % 15 === 0) console.log("FizzBuzz");
  else if (i % 3 === 0) console.log("Fizz");
  else if (i % 5 === 0) console.log("Buzz");
  else console.log(i);
}

