let datos = [1, 2, 3, 4, 5];
const usados = new Set();
function pintar(clase) {
  arr.innerHTML = "";
  datos.forEach(n => {
    const b = document.createElement("div");
    b.className = "box " + (clase || "");
    b.textContent = n;
    arr.appendChild(b);
  });
  code.textContent = "[" + datos.join(", ") + "]";
}
m.onclick = () => {
  datos = datos.map(n => n * 2);
  pintar("new");
  usados.add("map"); check();
};
f.onclick = () => {
  const boxes = [...arr.children];
  boxes.forEach((b, i) => { if (datos[i] % 2 !== 0) b.classList.add("out"); });
  setTimeout(() => { datos = datos.filter(n => n % 2 === 0); pintar(); }, 500);
  usados.add("filter"); check();
};
r.onclick = () => { datos = [1, 2, 3, 4, 5]; pintar("new"); };
function check() { if (usados.size === 2) CardLearner.complete(); }
pintar();

